.tic1,.tic1 *{fill: rgba(255,255,255,.15);color: #fbfeff;transition:unset;box-sizing:border-box}@keyframes fibb{0%{opacity:0}100%{opacity:1}}@keyframes tic2Loader{0%{transform:rotate(0)}100%{transform:rotate(360deg)}}.tic1{display:flex;flex-direction:row;width:100%;height:40px;align-items:center;border:solid 2px var(--themeC);padding:0;margin:10px 0;overflow:hidden;border-radius:5px}.tic1-title{display:flex;align-items:center;background-color:var(--themeC);color:#fff;height:100%;padding:0 10px;flex-shrink:0;gap:5px;position:relative}.tic1-rail,.tic1-train{width:100%;height:40px}.tic1-title:after{content:"";display:inline-block;width:0;height:0;border-top:10px solid transparent;border-bottom:10px solid transparent;border-right:solid 10px var(--themeC);position:absolute;left:0;margin-left:-10px;z-index:1}.tic1-rail{position:relative;overflow:hidden;opacity:1}.tic1-train{display:flex;flex-direction:row;align-items:center;position:absolute;top:0;right:0}.tic1-trailer{color:#08102b; display:flex;align-items:center;column-gap:5px;padding:2px 10px;flex-shrink:0;text-decoration:none;border-left:solid 1px var(--themeC);transition:.25s;animation:.5s linear fibb}.tic1-trailer:hover{color:var(--themeC)}.tic1-loader{display:block;width:20px;height:20px;border:solid 2px var(--themeC);border-right-color:transparent;border-bottom-color:transparent;border-radius:100%;animation:.7s linear infinite tic2Loader;margin-right:20px}
/* الوضع الليلي آخر الأخبار .drK */
