/* ================= [KD] شريط آخر الأخبار (الرئيسية فقط) - JS: كتلة kTkr في آخر القالب
   الحركة بـ CSS على كرت الشاشة (لا تشغل المعالج) - تتوقف عند المرور بالفأرة أو التركيز أو زر الإيقاف أو خروج الشريط من الشاشة
   الألوان من متغيرات القالب فتتبع لون الثيم والوضع الليلي تلقائيا ================= */
.kTkr{--tk:var(--kAcc);--tkD:color-mix(in srgb,var(--kAcc) 68%,#000);position:relative;display:flex;align-items:stretch;height:46px;margin:10px 0 20px;background:var(--kSrB);color:var(--kSrC);border:1px solid var(--kSrL);border-radius:14px;overflow:hidden;box-shadow:0 6px 22px rgba(0,0,0,.05);font-family:var(--fontB)}
.kTkrH{position:relative;z-index:2;flex:0 0 auto;display:flex;align-items:center;gap:9px;padding:0 16px 0 14px;background:#00574f;background:var(--tkD);color:#fff;font-size:13.5px;font-weight:700;white-space:nowrap}
.kTkrH::after{content:'';position:absolute;top:0;bottom:0;left:-9px;width:18px;background:inherit;transform:skewX(-14deg);z-index:-1}
.kTkrH svg{width:19px;height:19px;flex:0 0 19px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.kTkrDot{position:relative;width:8px;height:8px;flex:0 0 8px;border-radius:50%;background:#fff}
.kTkrDot::after{content:'';position:absolute;inset:0;border-radius:50%;background:#fff;animation:kTkrPulse 1.8s ease-out infinite}
@keyframes kTkrPulse{0%{transform:scale(1);opacity:.7}100%{transform:scale(2.8);opacity:0}}
.kTkrR{position:relative;flex:1 1 auto;min-width:0;overflow:hidden;-webkit-mask-image:linear-gradient(to left,transparent 0,#000 22px,#000 calc(100% - 28px),transparent 100%);mask-image:linear-gradient(to left,transparent 0,#000 22px,#000 calc(100% - 28px),transparent 100%)}
.kTkrT{position:absolute;top:0;bottom:0;right:0;display:flex;align-items:center;width:max-content}
.kTkr.is-ready .kTkrT{animation:kTkrMove var(--kTkrD,40s) linear infinite;will-change:transform}
@keyframes kTkrMove{from{transform:translateX(0)}to{transform:translateX(50%)}}
.kTkr:hover .kTkrT,.kTkr:focus-within .kTkrT,.kTkr.is-paused .kTkrT,.kTkr.is-off .kTkrT{animation-play-state:paused}
.kTkrS{display:flex;align-items:center;flex:0 0 auto}
.kTkrI{display:inline-flex;align-items:center;gap:8px;height:46px;padding:0 14px 0 18px;color:inherit;font-size:14px;white-space:nowrap;text-decoration:none;transition:color .2s}
.kTkrI::before{content:'';width:6px;height:6px;flex:0 0 6px;border-radius:2px;background:var(--tk);transform:rotate(45deg);opacity:.75}
.kTkrI:hover,.kTkrI:focus-visible{color:var(--tk);outline:0}
.kTkrI:hover .kTkrX,.kTkrI:focus-visible .kTkrX{text-decoration:underline;text-underline-offset:4px}
.kTkrN{flex:0 0 auto;padding:1px 8px;border-radius:20px;background:color-mix(in srgb,var(--tk) 16%,transparent);color:inherit;font-size:11px;font-weight:700;line-height:1.7}
.kTkrW{display:flex;align-items:center;gap:10px;height:46px;padding:0 16px;font-size:13px;opacity:.7}
.kTkrW::before{content:'';width:15px;height:15px;border:2px solid var(--tk);border-right-color:transparent;border-radius:50%;animation:kTkrSpin .7s linear infinite}
@keyframes kTkrSpin{to{transform:rotate(360deg)}}
.kTkrP{flex:0 0 44px;display:flex;align-items:center;justify-content:center;width:44px;padding:0;border:0;border-right:1px solid var(--kSrL);background:transparent;color:inherit;cursor:pointer;opacity:.7;transition:opacity .2s,background .2s}
.kTkrP:hover,.kTkrP:focus-visible{opacity:1;background:color-mix(in srgb,var(--tk) 10%,transparent);outline:0}
.kTkrP svg{width:18px;height:18px;fill:currentColor}
.kTkrP .kPl,.kTkr.is-paused .kTkrP .kPs{display:none}
.kTkr.is-paused .kTkrP .kPl{display:block}
@media (max-width:640px){.kTkr{height:42px;border-radius:12px}.kTkrH{padding:0 12px 0 10px;gap:7px}.kTkrH b{display:none}.kTkrI,.kTkrW{height:42px;font-size:13.5px}.kTkrP{flex-basis:40px;width:40px}}
@media (prefers-reduced-motion:reduce){.kTkr.is-ready .kTkrT{animation:none;position:static}.kTkrR{overflow-x:auto;-webkit-mask-image:none;mask-image:none}.kTkrS[aria-hidden]{display:none}.kTkrP,.kTkrDot::after{display:none}}

document.querySelectorAll(".tic1").forEach(t=>{var e=100/parseInt(t.dataset.speed);function r(){var t=!1,r=document.querySelector(".tic1");r.addEventListener("mouseover",function(){t=!0}),r.addEventListener("mouseout",function(){t=!1});var a=document.querySelector(".tic1-train");a.getBoundingClientRect().width;var n=0;document.querySelectorAll(".tic1-train .tic1-trailer").forEach(t=>{n+=t.getBoundingClientRect().width});var l=n/2,i=0;setInterval(function(){i<l?a.style.transform="translateX("+i+"px)":i=0,!1===t&&(i+=1)},e)}function a(t){var e=t.feed.entry,r=e.length;var a="";for(let l=0;l<r;l++){var i=n(e[l]);a+="<a class='tic1-trailer' href='"+i[1]+"' title='"+i[0]+"'>"+i[0]+"</a>"}return a+a}function n(t){var e=t.link,r=[];for(let a=0;a<e.length;a++)"alternate"===e[a].rel&&(r.push(e[a].title),r.push(e[a].href));return r}e=Math.floor(e);var l,i=t.dataset.label,o="/feeds/posts/summary?alt=json&max-results="+t.dataset.results;"recent"!==i&&(o=o.replace("/summary?","/summary/-/"+i+"?")),0;var kd=[],ks={};"recent"===i&&document.querySelectorAll("#Blog1 .pTtl a[href]").forEach(function(x){var h=x.getAttribute("href");if(!ks[h]&&kd.length<parseInt(t.dataset.results||5)){ks[h]=1;kd.push({link:[{rel:"alternate",title:(x.getAttribute("data-text")||x.textContent).trim().replace(/['<>]/g,""),href:h}]})}});if(kd.length){t.querySelector(".tic1-train").innerHTML=a({feed:{entry:kd}});setTimeout(function(){r()},1e3)}else fetch(o,{method:"GET",redirect:"follow"}).then(t=>t.text()).then(e=>{var n=JSON.parse(e),l=a(n);t.querySelector(".tic1-train").innerHTML=l,setTimeout(function(){r()},1e3)})});
