/* ---------- [KD] شريط آخر الأخبار kTkr ----------
   العناوين من مقالات الصفحة الرئيسية نفسها (بلا أي طلب إضافي)، وإن لم تكف أو كان data-label تصنيفا تجلب من تغذية المدونة
   نسختان من العناوين تتحركان بـ CSS حركة دائرية بلا انقطاع، وشارة «جديد» للمقالات المنشورة خلال 3 أيام ---------- */
(function(){
  var box=document.querySelector('.kTkr'); if(!box) return;
  var track=box.querySelector('.kTkrT'),btn=box.querySelector('.kTkrP');
  var max=parseInt(box.getAttribute('data-results'),10)||6,label=box.getAttribute('data-label')||'recent',speed=parseFloat(box.getAttribute('data-speed'))||45,DAY=864e5;
  function esc(v){return String(v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function item(p,clone){
    var fresh=p.date&&Date.now()-p.date<3*DAY;
    return "<a class='kTkrI' href='"+esc(p.href)+"'"+(clone?" tabindex='-1'":"")+">"+(fresh?"<span class='kTkrN'>جديد</span>":"")+"<span class='kTkrX'>"+esc(p.title)+"</span></a>";
  }
  function timing(w){ track.style.setProperty('--kTkrD',Math.max(14,Math.round(w/speed))+'s'); }
  function render(list){
    if(!list.length){ box.hidden=true; return; }
    var a='',b='',chars=0;
    list.forEach(function(p){ a+=item(p); b+=item(p,1); chars+=p.title.length; });
    track.innerHTML="<div class='kTkrS'>"+a+"</div><div class='kTkrS' aria-hidden='true'>"+b+"</div>";
    timing(chars*7.2+list.length*48);                 /* تقدير أولي دون قياس الصفحة */
    box.classList.add('is-ready');
    var fix=function(){ var s=track.firstChild; s&&timing(s.offsetWidth); };   /* قياس دقيق مرة واحدة حين يكون المتصفح متفرغا */
    (document.fonts&&document.fonts.ready?document.fonts.ready:Promise.resolve()).then(function(){ (window.requestIdleCallback||setTimeout)(fix); });
  }
  function fromPage(){
    var out=[],seen={};
    [].forEach.call(document.querySelectorAll('#Blog1 .ntry'),function(n){
      var a=n.querySelector('.pTtl a[href]'); if(!a||out.length>=max) return;
      var h=a.getAttribute('href'); if(seen[h]) return; seen[h]=1;
      var t=n.querySelector('time[datetime]');
      out.push({href:h,title:(a.getAttribute('data-text')||a.textContent).trim(),date:t?Date.parse(t.getAttribute('datetime')):0});
    });
    return out;
  }
  function fromFeed(){
    var u='/feeds/posts/summary'+(label!=='recent'?'/-/'+encodeURIComponent(label):'')+'?alt=json&max-results='+max;
    fetch(u).then(function(r){return r.json()}).then(function(j){
      render(((j.feed&&j.feed.entry)||[]).map(function(e){
        var l=(e.link||[]).filter(function(x){return x.rel==='alternate'})[0]||{};
        return {href:l.href,title:(e.title&&e.title.$t)||'',date:Date.parse(e.published&&e.published.$t)||0};
      }).filter(function(p){return p.href&&p.title}));
    }).catch(function(){ box.hidden=true; });
  }
  var page=label==='recent'?fromPage():[];
  if(page.length>=3) render(page); else fromFeed();
  btn&&btn.addEventListener('click',function(){
    var p=box.classList.toggle('is-paused');
    btn.setAttribute('aria-pressed',p?'true':'false');
    btn.setAttribute('aria-label',p?'تشغيل الشريط':'إيقاف الشريط مؤقتا');
  });
  if('IntersectionObserver' in window) new IntersectionObserver(function(en){ box.classList.toggle('is-off',!en[0].isIntersecting); }).observe(box);
})();
/* ---------- [KD] شريط التقدم العلوي: يتحدث مرة واحدة لكل إطار أثناء التمرير، ولا يمسح أحداث التمرير الأخرى ---------- */
(function(){
  var bar=document.getElementById('myBar'); if(!bar) return; var raf=0;
  function upd(){ raf=0; var d=document.documentElement,h=d.scrollHeight-d.clientHeight; bar.style.width=(h>0?Math.min(100,(window.pageYOffset||d.scrollTop)/h*100):0)+'%'; }
  window.addEventListener('scroll',function(){ if(!raf) raf=requestAnimationFrame(upd); },{passive:true});
  upd();
})();
